-- Run in the synthetic demo project after pnpm seed:demo.
begin;

do $$
begin
  if (select count(*) from auth.users u join public.profiles p on p.id = u.id
      where u.raw_app_meta_data ->> 'kinetria_demo' = 'true'
        and p.active and (u.email, p.role::text) in (
          ('employee@kinetria.example', 'employee'),
          ('manager@kinetria.example', 'manager'),
          ('handler@kinetria.example', 'handler')
        )) <> 3 then
    raise exception 'Provision the three Kinetria demo accounts first.';
  end if;
end;
$$;

-- The demo uses one shared manager queue; timing intentionally uses the reserve.
insert into kinetria_private.category_routes (category_id, assignee_id)
select c.id, u.id
from public.request_categories c
join auth.users u on u.email = case when c.id in ('catalog', 'training')
  then 'handler@kinetria.example' else 'manager@kinetria.example' end
where c.id <> 'timing'
on conflict (category_id) do nothing;

with samples (source_ref, category_id, kind, status, title, description, outcome) as (values
  ('A-001', 'collaboration', 'problem', 'new', 'Обязательные поля в заявке на оборудование', 'В заявках на приобретение оборудования иногда не хватает назначения изделия и требуемых параметров. Предлагаю добавить обязательные поля, чтобы сократить число уточнений.', 'Запросить пример корректно заполненной заявки; оценить изменение шаблона.'),
  ('A-002', 'visibility', 'idea', 'review', 'Краткий статус проекта для закупок', 'При общении с поставщиками полезно видеть общую стадию проекта без доступа к коммерческим деталям. Можно ли показывать краткий статус и ориентировочные контрольные даты?', 'Определить перечень доступных статусов и источник их обновления.'),
  ('A-003', 'catalog', 'problem', 'in_progress', 'Разные обозначения одного изделия', 'В рабочих материалах иногда встречаются разные обозначения одного изделия. Это увеличивает время проверки спецификации. Нужен понятный способ находить актуальную карточку позиции.', 'Подготовить правило проверки и корректировки номенклатуры.'),
  ('A-004', 'training', 'idea', 'implemented', 'Календарь обучающих встреч', 'Было бы полезно проводить короткие занятия по новым товарным линейкам с разбором типовых запросов. Предлагаю составить календарь таких встреч.', 'Пример результата: запланирован пробный обучающий семинар.'),
  ('A-005', 'documents', 'problem', 'clarification', 'Статусы пакетов документов', 'При обработке документов между подразделениями возникают дополнительные вопросы о том, на каком этапе находится пакет. Хотелось бы видеть ответственного и текущий статус.', 'Уточнить виды документов и ключевые этапы согласования.'),
  ('A-006', 'processes', 'idea', 'review', 'Памятка для совместных операций', 'Предлагаю собрать короткую пошаговую памятку для операций, в которых последовательно участвуют несколько подразделений, и определить порядок актуализации памятки.', 'Назначить владельца процесса и согласовать черновик инструкции.'),
  ('A-007', 'it', 'problem', 'new', 'Повторный ввод данных', 'Иногда повторный ввод одних и тех же сведений в разных рабочих системах занимает много времени. Нужна оценка, какие операции можно синхронизировать безопасно.', 'Собрать примеры операций и оценить техническую реализуемость.'),
  ('A-008', 'mentoring', 'idea', 'implemented', 'Памятка для новых сотрудников', 'При передаче сложной задачи новому сотруднику полезен короткий разбор типовых ошибок и контактов, к которым можно обратиться за помощью. Предлагаю сделать такую памятку.', 'Пример результата: создана учебная инструкция.'),
  ('A-009', 'contracts', 'problem', 'in_progress', 'Ответственные за приложения к договору', 'Не всегда понятно, кто готовит очередную версию приложения к договору и кто должен проверить её перед отправкой. Это приводит к повторным согласованиям.', 'Разграничить этапы подготовки, проверки и утверждения.'),
  ('A-010', 'tasks', 'idea', 'review', 'Подтверждение результата задачи', 'Предлагаю не закрывать рабочую задачу до подтверждения заказчиком результата внутри компании, чтобы связанные вопросы оставались в общей истории обсуждения.', 'Проверить, подходит ли правило для разных типов задач.'),
  ('A-011', 'timing', 'problem', 'new', 'Срок ответа смежных подразделений', 'При срочной подготовке клиентского предложения сложно прогнозировать сроки ответа от смежных подразделений. Хотелось бы видеть ожидаемый срок и уведомление при задержке.', 'Определить допустимые сроки реакции для разных категорий.'),
  ('A-012', 'communication', 'idea', 'review', 'Единое место для итогов обсуждения', 'Рабочие обсуждения распределены по нескольким каналам, из-за чего теряется контекст. Предлагаю выбрать единое место для итоговых решений по задаче.', 'Сравнить варианты и предложить правила фиксации итогов.'),
  ('A-013', 'projects', 'problem', 'clarification', 'История изменений спецификации', 'Когда изменяется состав оборудования в проекте, не всегда ясно, какие строки спецификации были пересмотрены. Нужна более заметная история изменений.', 'Уточнить формат исходных файлов и способы сравнения версий.'),
  ('A-014', 'planning', 'idea', 'review', 'Планирование загрузки проектной группы', 'Предлагаю показывать загруженность проектной группы на ближайшие недели в укрупнённом виде. Так будет проще согласовывать сроки запуска новых задач.', 'Согласовать показатели загрузки и права просмотра.'),
  ('A-015', 'briefs', 'problem', 'in_progress', 'Шаблон постановки задач', 'Некоторые поручения поступают без ожидаемого результата и даты завершения. Предлагаю договориться о минимальном наборе данных при постановке задачи.', 'Подготовить шаблон с целью, сроком, приоритетом и ответственным.'),
  ('A-016', 'training', 'idea', 'new', 'Практические занятия по оборудованию', 'Для новых сотрудников полезны практические демонстрации оборудования, а не только презентации. Предлагаю пилотное занятие с учебными образцами.', 'Проверить наличие образцов и составить план пилота.'),
  ('A-017', 'workplace', 'idea', 'rejected', 'Зона для коротких перерывов', 'Предлагаю организовать отдельную небольшую зону для коротких перерывов рядом с рабочими помещениями.', 'Пример мотивированного ответа: сейчас нет подходящего помещения; вернуться к вопросу при перепланировке.'),
  ('A-018', 'workplace', 'praise', 'closed', 'Отзыв о внутренних учебных встречах', 'Хочу отметить пользу внутренних учебных встреч: после них стало легче обращаться к коллегам за консультацией. Было бы хорошо сохранить этот формат.', 'Зафиксировать положительный отзыв и передать организаторам обучения.'),
  ('A-019', 'filing', 'problem', 'review', 'Актуальные редакции инструкций', 'В общих папках трудно быстро определить актуальную редакцию инструкции. Можно ли закрепить единые правила именования и архивирования старых версий?', 'Согласовать порядок хранения и владельцев папок.'),
  ('A-020', 'results', 'idea', 'new', 'Обзор завершённых улучшений', 'Предлагаю публиковать краткий обзор завершённых внутренних улучшений, чтобы сотрудники видели результат направленных предложений.', 'Рассмотреть формат квартальной подборки без конфиденциальных сведений.')
), imported as (
  insert into public.requests (source_ref, author_id, assignee_id, submission_key, category_id,
    kind, status, title, description, decision, next_step)
  select s.source_ref, author.id, r.assignee_id, gen_random_uuid(), s.category_id,
    s.kind::public.request_kind, s.status::public.request_status, s.title, s.description,
    case when s.status in ('implemented', 'rejected', 'closed') then s.outcome end,
    case when s.status = 'in_progress' then s.outcome end
  from samples s
  join auth.users author on author.email = 'employee@kinetria.example'
  left join kinetria_private.category_routes r on r.category_id = s.category_id
  on conflict (source_ref) do nothing
  returning id, source_ref, status, decision, next_step
)
insert into public.request_events (request_id, actor_role, event_type, status, message, next_step)
select i.id, e.actor_role::public.kinetria_role, e.event_type, e.status, e.message, e.next_step
from imported i join samples s using (source_ref)
cross join lateral (
  select 1 as sequence, 'employee' as actor_role, 'created' as event_type,
    'new'::public.request_status as status, null::text as message, null::text as next_step
  union all
  select 2, 'manager', 'reviewed', i.status,
    case when i.status = 'clarification' then s.outcome else i.decision end, i.next_step
  where i.status <> 'new'
) e order by i.source_ref, e.sequence;

commit;
